<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ApiError, assetCategoryLabels, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import type { ClassificationRecord } from './classification-standards'
import CapabilityAssetPicker from './CapabilityAssetPicker.vue'
interface Doc {id:number;name:string;sourceUrl:string;content:string;enabled:boolean;allowAi:boolean;revision:number;digest:string;updatedAt:string}
interface Reference {id:number;name:string;sourceUrl:string;revision:number;digest:string;excerpt:string;score:number}
interface Profile {id:number;name:string;model:string;enabled:boolean;allowMetadata:boolean;revision:number}
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>();const base=workspacePath(props.workspace.slug)+'/classification',owner=computed(()=>props.workspace.role==='owner'),editor=computed(()=>['owner','operator'].includes(props.workspace.role))
const docs=ref<Doc[]>([]),editing=ref<Doc|null>(null),showForm=ref(false),form=reactive({name:'',sourceUrl:'',content:'',enabled:true,allowAi:false}),busy=ref(false),error=ref(''),notice=ref(''),asset=ref<ClassificationRecord>(),references=ref<Reference[]>([]),checked=ref<number[]>([]),profileId=ref(''),profiles=ref<Profile[]>([]),hybrid=ref(false),sending=ref(false),authorized=ref(false),suggestion=ref<{category:string;rationale:string;model:string;createdAt:string;assetRevision:number}|null>(null),metadata=ref<unknown>();const active=new AbortController();let searchSequence=0
const selectedProfile=computed(()=>profiles.value.find(p=>String(p.id)===profileId.value)),selectedRefs=computed(()=>references.value.filter(r=>checked.value.includes(r.id)))
function failed(e:unknown){if(active.signal.aborted)return;if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=e instanceof Error&&!(e instanceof ApiError)&&!(e instanceof TypeError)?e.message:describeError(e)}
async function load(){try{const [d,e]=await Promise.all([request<{items:Doc[]}>(base+'/knowledge',{signal:active.signal}),request<{settings:{mode:string};profiles:Profile[]}>(base+'/engine',{signal:active.signal})]);docs.value=d.items;profiles.value=e.profiles.filter(p=>p.enabled&&p.allowMetadata);hybrid.value=e.settings.mode==='hybrid'}catch(e){failed(e)}}
function edit(doc?:Doc){editing.value=doc||null;Object.assign(form,doc?{name:doc.name,sourceUrl:doc.sourceUrl,content:doc.content,enabled:doc.enabled,allowAi:doc.allowAi}:{name:'',sourceUrl:'',content:'',enabled:true,allowAi:false});showForm.value=true;error.value=''}
async function save(){if(!owner.value||busy.value)return;busy.value=true;error.value='';try{if(new TextEncoder().encode(form.content).length>32768)throw new Error('知识正文不得超过32KiB。');await request(base+'/knowledge'+(editing.value?'/'+editing.value.id:''),{method:editing.value?'PUT':'POST',body:JSON.stringify({...form,revision:editing.value?.revision||0}),signal:active.signal});showForm.value=false;await load();notice.value='知识文档已保存。更新后的文档版本会在下次检索重新采用。'}catch(e){failed(e)}finally{busy.value=false}}
async function retrieve(){if(!asset.value||!editor.value)return;const seq=++searchSequence,current={id:asset.value.asset.id,revision:asset.value.revision};busy.value=true;error.value='';references.value=[];checked.value=[];authorized.value=false;suggestion.value=null;metadata.value=undefined;try{const [r,m]=await Promise.all([request<{references:Reference[]}>(base+'/knowledge/search',{method:'POST',body:JSON.stringify({assetId:Number(current.id),revision:current.revision}),signal:active.signal}),request<{metadata:unknown}>(base+'/ai/input?assetId='+current.id+'&revision='+current.revision,{signal:active.signal})]);if(seq!==searchSequence)return;references.value=r.references;metadata.value=m.metadata;notice.value='本地词项检索已完成，尚未调用外部模型。请选择可发送的知识摘录。'}catch(e){if(seq===searchSequence)failed(e)}finally{if(seq===searchSequence)busy.value=false}}
async function suggest(){if(!asset.value||!hybrid.value||!selectedProfile.value||!selectedRefs.value.length||!authorized.value||sending.value)return;const seq=searchSequence;sending.value=true;error.value='';try{const result=await request<typeof suggestion.value>(base+'/knowledge/suggest',{method:'POST',body:JSON.stringify({assetId:Number(asset.value.asset.id),revision:asset.value.revision,profileId:Number(profileId.value),allowKnowledge:true,references:selectedRefs.value.map(r=>({id:r.id,revision:r.revision,digest:r.digest}))}),signal:active.signal});if(seq===searchSequence)suggestion.value=result}catch(e){if(seq===searchSequence)failed(e)}finally{sending.value=false}}
watch(asset,()=>{searchSequence++;references.value=[];checked.value=[];metadata.value=undefined;suggestion.value=null;authorized.value=false;busy.value=false})
watch([profileId,checked],()=>{authorized.value=false;suggestion.value=null},{deep:true})
onMounted(load);onBeforeUnmount(()=>{active.abort();form.content='';metadata.value=undefined})
</script>
<template><section class="knowledge-panel"><div class="panel-heading"><div><h2>分类知识与参考建议</h2><p>维护带版本的知识文档，先在本地检索，再由用户选择摘录是否发送至已配置模型。建议仍需人工采用。</p></div><button v-if="owner" class="button button-primary" @click="edit()">新增知识文档</button></div><p v-if="error" class="message message-error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
<form v-if="showForm" class="panel knowledge-form" @submit.prevent="save"><h3>{{editing?'修订知识文档':'新增知识文档'}}</h3><label>文档名称<input v-model="form.name" maxlength="120" required></label><label>依据链接（可选）<input v-model="form.sourceUrl" type="url" maxlength="1000"></label><label>正文（最多32KiB）<textarea v-model="form.content" rows="9" required></textarea></label><label class="check"><input v-model="form.enabled" type="checkbox">启用本地检索</label><label class="check"><input v-model="form.allowAi" type="checkbox">允许经用户逐次确认后，将文档摘录发送至所选AI模型</label><div class="actions"><button class="button" type="button" @click="showForm=false">取消</button><button class="button button-primary" :disabled="busy">保存文档版本</button></div></form>
<section class="panel"><div class="panel-heading"><h3>知识文档 · {{docs.length}}份</h3></div><p v-if="!docs.length" class="message">尚未登记知识文档。负责人可加入实际采用的业务规则、分类标准解释与内部指引。</p><div v-else class="table-wrap"><table><thead><tr><th>文档 / 修订</th><th>本地检索</th><th>AI摘录权限</th><th>更新</th><th>操作</th></tr></thead><tbody><tr v-for="doc in docs" :key="doc.id"><th scope="row">{{doc.name}}<small>修订{{doc.revision}} · {{doc.digest.slice(0,12)}}…</small></th><td>{{doc.enabled?'已启用':'已暂停'}}</td><td>{{doc.allowAi?'仍需逐次确认':'仅本地'}}</td><td>{{formatDate(doc.updatedAt)}}</td><td><button v-if="owner" class="button" @click="edit(doc)">修订</button><details><summary>查看正文</summary><pre>{{doc.content}}</pre></details></td></tr></tbody></table></div></section>
<section class="panel knowledge-form"><h3>为实际资产检索参考</h3><CapabilityAssetPicker :workspace="workspace" @change="asset=$event" @session-expired="emit('sessionExpired')"/><p v-if="asset">当前资产 #{{asset.asset.id}} · {{asset.asset.name}} · 分类修订{{asset.revision}}</p><button class="button" :disabled="!asset||!editor||busy" @click="retrieve">{{busy?'本地检索中…':'本地检索知识'}}</button><p v-if="!editor">当前角色可查看配置，知识检索与参考建议需操作员或负责人权限。</p>
<template v-if="metadata!==undefined"><details><summary>查看实际资产元数据预览</summary><pre>{{JSON.stringify(metadata,null,2)}}</pre></details><p v-if="!references.length">没有匹配到已启用的知识摘录。该结果不代表不存在适用规定。</p><article v-for="reference in references" :key="reference.id" class="knowledge-ref"><label class="check"><input v-model="checked" type="checkbox" :value="reference.id" :disabled="!docs.find(d=>d.id===reference.id)?.allowAi">{{reference.name}} · 修订{{reference.revision}}</label><p>{{reference.excerpt}}</p><small>摘录摘要 {{reference.digest}} · {{docs.find(d=>d.id===reference.id)?.allowAi?'可选择发送':'该文档未授权AI发送'}}</small></article><label>选择AI配置<select v-model="profileId"><option value="">请选择已授权的模型配置</option><option v-for="p in profiles" :key="p.id" :value="String(p.id)">{{p.name}} · {{p.model}}</option></select></label><p v-if="!hybrid">当前为本地模式。请先在“识别引擎与AI”配置中明确启用混合模式。</p><label class="check"><input v-model="authorized" type="checkbox" :disabled="!selectedRefs.length||!hybrid">允许发送预览中的资产名称、系统、字段名与类型，以及所选{{selectedRefs.length}}份知识摘录（不含原始记录或注释）</label><button class="button button-primary" :disabled="!editor||!hybrid||!selectedProfile||!selectedRefs.length||!authorized||sending" @click="suggest">{{sending?'生成中…':'生成知识增强参考建议（可能产生模型费用）'}}</button></template>
<article v-if="suggestion" class="knowledge-ref"><h3>AI参考建议 · {{assetCategoryLabels[suggestion.category]||suggestion.category}}</h3><p>{{suggestion.rationale}}</p><small>{{suggestion.model}} · {{formatDate(suggestion.createdAt)}} · 资产修订{{suggestion.assetRevision}}</small><p>只作为人工核对参考，不自动采用，不认定重要数据或核心数据。</p></article></section></section></template>
<style scoped>.knowledge-panel{display:grid;gap:18px;min-width:0}.knowledge-panel>.panel-heading{padding:0}.knowledge-panel h2{font-size:18px}.knowledge-panel h3{font-size:15px}.knowledge-panel p{font-size:12px;line-height:1.85;color:var(--secondary)}.knowledge-form{display:grid;gap:15px;padding:20px}.knowledge-form label{display:grid;gap:7px;font-size:12px}.knowledge-form .check{display:flex;align-items:flex-start;gap:8px}.knowledge-form input:not([type=checkbox]),.knowledge-form textarea,.knowledge-form select{font:inherit;border:1px solid var(--input-line);border-radius:6px;padding:9px 10px;background:var(--surface);color:var(--ink);min-width:0;max-width:100%}.knowledge-form>.button{justify-self:start}.knowledge-panel table{width:100%;min-width:700px;border-collapse:collapse}.knowledge-panel th,.knowledge-panel td{font-size:12px;padding:13px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}.knowledge-panel small{display:block;font-size:11px;font-weight:400;color:var(--secondary);margin-top:5px;overflow-wrap:anywhere}.knowledge-panel details{font-size:12px;margin-top:8px}.knowledge-panel summary{cursor:pointer;color:var(--accent)}.knowledge-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-width:700px;max-height:330px;overflow:auto}.knowledge-ref{border-top:1px solid var(--line);padding:15px 0}.actions{display:flex;gap:10px;justify-content:flex-end}</style>
